{
  "name": "@dokploy/cli",
  "description": "A CLI to manage dokploy server remotely",
  "version": "0.30.7",
  "author": "Mauricio Siu",
  "licenses": [
    {
      "type": "MIT",
      "url": "https://github.com/Dokploy/cli/blob/master/LICENSE"
    }
  ],
  "publishConfig": {
    "access": "public"
  },
  "bin": {
    "dokploy": "./dist/index.js"
  },
  "bugs": "https://github.com/Dokploy/cli/issues",
  "dependencies": {
    "axios": "^1.20.0",
    "chalk": "^5.6.2",
    "commander": "^13.1.0"
  },
  "devDependencies": {
    "@biomejs/biome": "2.1.1",
    "@types/node": "^18.19.130",
    "tsx": "^4.23.15",
